<?php
require_once __DIR__ . '/../config/database.php';
require_once __DIR__ . '/../config/session.php';

start_app_session();

$setup = $_SESSION['google_password_setup'] ?? null;
$csrf = (string)($_SESSION['google_password_csrf'] ?? '');
$validSetup = is_array($setup)
    && !empty($setup['tenant_id'])
    && !empty($setup['email'])
    && (int)($setup['expires_at'] ?? 0) >= time()
    && $csrf !== '';

if (!$validSetup) {
    unset($_SESSION['google_password_setup'], $_SESSION['google_password_csrf']);
    $_SESSION['auth_notice'] = 'Your Google password setup link expired. Sign in with Google again.';
    header('Location: login.php', true, 303);
    exit;
}

$errorMessage = '';
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') {
    $submittedToken = (string)($_POST['csrf_token'] ?? '');
    $password = $_POST['password'] ?? '';
    $confirmPassword = $_POST['confirm_password'] ?? '';

    if (!hash_equals($csrf, $submittedToken)) {
        $errorMessage = 'Your session expired. Sign in with Google again.';
    } elseif (!is_string($password) || !preg_match('/^(?=.*[A-Z])(?=.*[a-z])(?=.*[0-9])(?=.*[^A-Za-z0-9\s])\S{8,16}$/', $password)) {
        $errorMessage = 'Password must be 8–16 characters with uppercase, lowercase, a number, and a symbol (no spaces).';
    } elseif (!is_string($confirmPassword) || !hash_equals($password, $confirmPassword)) {
        $errorMessage = 'The passwords do not match.';
    } else {
        try {
            $pdo = database();
            $statement = $pdo->prepare(
                "UPDATE tenants SET password_hash = ?
                 WHERE tenant_id = ? AND LOWER(email) = LOWER(?) AND (password_hash IS NULL OR password_hash = '')"
            );
            $statement->execute([
                password_hash($password, PASSWORD_DEFAULT),
                (string)$setup['tenant_id'],
                (string)$setup['email'],
            ]);

            $check = $pdo->prepare('SELECT tenant_id, first_name, last_name, email, profile_photo, profile_completed, account_status FROM tenants WHERE tenant_id = ? LIMIT 1');
            $check->execute([(string)$setup['tenant_id']]);
            $tenant = $check->fetch();
            if (!$tenant || ($tenant['account_status'] ?? 'active') === 'suspended') {
                throw new RuntimeException('The tenant account is unavailable.');
            }

            session_regenerate_id(true);
            unset($_SESSION['google_password_setup'], $_SESSION['google_password_csrf']);
            $_SESSION['user_id'] = (string)$tenant['tenant_id'];
            $_SESSION['role'] = 'tenant';
            $_SESSION['user'] = [
                'id' => (string)$tenant['tenant_id'],
                'name' => trim((string)$tenant['first_name'] . ' ' . (string)$tenant['last_name']) ?: (string)$tenant['email'],
                'email' => (string)$tenant['email'],
                'photo' => (string)($tenant['profile_photo'] ?? ''),
            ];
            remember_authenticated_account((string)$tenant['tenant_id'], 'tenant');

            if (empty($tenant['profile_completed'])) {
                $_SESSION['profile_completion_required'] = true;
                $_SESSION['profile_onboarding_phase'] = 'prompt';
                header('Location: ../tenant/dashboard.php', true, 303);
            } else {
                unset($_SESSION['profile_completion_required'], $_SESSION['profile_onboarding_phase']);
                header('Location: ../tenant/dorms.php', true, 303);
            }
            exit;
        } catch (Throwable $error) {
            error_log('UniStay Google password setup failed: ' . $error->getMessage());
            $errorMessage = 'Your UniStay password could not be saved. Sign in with Google and try again.';
        }
    }
}
